import{_ as t,o,c as a,a2 as d}from"./chunks/framework.BGlkWkwp.js";const u=JSON.parse('{"title":"ProcessDialog","description":"","frontmatter":{},"headers":[],"relativePath":"workbench/process-dialog.md","filePath":"workbench/process-dialog.md"}'),r={name:"workbench/process-dialog.md"};function n(s,e,c,i,h,l){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="processdialog" tabindex="-1">ProcessDialog <a class="header-anchor" href="#processdialog" aria-label="Permalink to &quot;ProcessDialog&quot;">​</a></h1><p>ProcessDialog is the frame of a dialog that runs a process: what it does, its fields, and the actions to run it or to cancel it.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for an operation that takes settings before it runs, such as a conversion, an export or an operation on a selection. The application passes the fields as children, runs the process on <code>onrun</code>, sets <code>running</code> (and <code>progress</code> when it can tell) while it runs, and closes the dialog when it is done. It shows why a run failed in <code>error</code>, and stops a run on <code>oncancel</code>. To ask before an action that takes no settings, use a <a href="./../components/confirm">Confirm</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>open</code></td><td><code>false</code></td><td>Whether the dialog is open (bindable)</td></tr><tr><td><code>title</code></td><td>required</td><td>The title in the head</td></tr><tr><td><code>description</code></td><td></td><td>What the process does, above the fields</td></tr><tr><td><code>error</code></td><td></td><td>Why the last run failed, in a red notice at the top</td></tr><tr><td><code>runLabel</code></td><td><code>run</code> message</td><td>The run action</td></tr><tr><td><code>runningText</code></td><td><code>running</code> message</td><td>What shows while running</td></tr><tr><td><code>running</code></td><td><code>false</code></td><td>The process runs</td></tr><tr><td><code>progress</code></td><td></td><td>How far it is, 0 to 100; without it, indeterminate</td></tr><tr><td><code>disabled</code></td><td><code>false</code></td><td>The run action cannot be pressed</td></tr><tr><td><code>onrun</code></td><td></td><td>Called when the run action is pressed</td></tr><tr><td><code>oncancel</code></td><td></td><td>Called when the user closes the dialog</td></tr><tr><td><code>size</code></td><td><code>md</code></td><td>The width, as <a href="./../components/modal">Modal</a>&#39;s <code>size</code></td></tr><tr><td><code>inline</code></td><td><code>false</code></td><td>The same surface in the flow of a page</td></tr><tr><td><code>children</code></td><td></td><td>The fields</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>A <a href="./../components/modal">Modal</a> whose body reads in a fixed order: the error in a <a href="./../components/banner">Banner</a>, the description, then the fields, gap-lg apart; the three are gap-md apart. The <a href="./../components/footer">Footer</a> holds cancel and the run action, the primary one. While running, the body shows a <a href="./../components/spinner">Spinner</a> with the running text and a <a href="./../components/progress">Progress</a> instead, and the run action is busy. Cancel, the close button and Escape call <code>oncancel</code> whenever they close the dialog, also while it runs; when the application closes it by setting <code>open</code> to false, <code>oncancel</code> is not called.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/process-dialog/" title="ProcessDialog" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/process-dialog/" target="_blank" rel="noopener">ProcessDialog</a></figcaption></figure>',10)])])}const f=t(r,[["render",n]]);export{u as __pageData,f as default};
